// Physical bindings map into stable canonical actions; multiplayer never depends on a friend's bindings.
const ACTIONS={forward:['Avançar','KeyW'],back:['Recuar','KeyS'],left:['Esquerda','KeyA'],right:['Direita','KeyD'],sprint:['Correr','ShiftLeft'],crouchToggle:['Agachar (alternar)','ControlLeft'],crouchHold:['Agachar (segurar)','KeyC'],jump:['Pular / abrir paraquedas','Space'],fire:['Atirar','Mouse0'],aim:['Mirar de perto','Mouse2'],reload:['Recarregar','KeyR'],weapon1:['Arma 1','Digit1'],weapon2:['Arma 2','Digit2'],weapon3:['Arma 3','Digit3'],heal25:['Kit +25','KeyH'],heal100:['Kit +100','KeyJ'],grenade:['Granada','KeyG'],ice:['Parede de gelo','KeyT'],loot:['Coletar loot','KeyE'],free:['Câmera livre (segurar)','KeyF'],vehicle:['Entrar / sair de veículo','KeyB'],vault:['Transpor janela','KeyV'],slide:['Deslizar','KeyQ'],inventory:['Inventário','Tab'],map:['Mapa','KeyM'],perspective:['Trocar perspectiva','F5'],pause:['Pausar / continuar','Escape'],settings:['Configurações','KeyO']};
const INPUT={bindings:Object.fromEntries(Object.entries(ACTIONS).map(([key,value])=>[key,value[1]])),menuOpen:false,listening:null,toggled:false,crouchHeld:false,held:new Map()};
function validBinding(code){return /^(Key[A-Z]|Digit[0-9]|F(?:[1-9]|1[0-2])|Mouse[0-4]|Arrow(?:Up|Down|Left|Right)|Shift(?:Left|Right)|Control(?:Left|Right)|Alt(?:Left|Right)|Space|Tab|Escape|Enter|Backspace|CapsLock|Backquote|Minus|Equal|BracketLeft|BracketRight|Semicolon|Quote|Comma|Period|Slash|Backslash)$/.test(code)}
try{const saved=JSON.parse(localStorage.getItem('lz-controls')||'null');if(saved&&typeof saved==='object'){const candidate={...INPUT.bindings};for(const key in candidate)if(typeof saved[key]==='string'&&validBinding(saved[key]))candidate[key]=saved[key];if(new Set(Object.values(candidate)).size===Object.keys(candidate).length)INPUT.bindings=candidate}}catch{}
function keyLabel(code){return ({Mouse0:'Mouse esquerdo',Mouse1:'Mouse central',Mouse2:'Mouse direito',Mouse3:'Mouse 4',Mouse4:'Mouse 5',Space:'Espaço',ControlLeft:'Ctrl',ControlRight:'Ctrl dir.',ShiftLeft:'Shift',ShiftRight:'Shift dir.',AltLeft:'Alt',AltRight:'Alt dir.',Escape:'Esc',ArrowUp:'↑',ArrowDown:'↓',ArrowLeft:'←',ArrowRight:'→',Backquote:'`'})[code]||code.replace(/^Key|^Digit/,'')}
function bindingLabel(action){return keyLabel(INPUT.bindings[action])}
function actionFor(code){const action=Object.keys(INPUT.bindings).find(key=>INPUT.bindings[key]===code);if(action)return action;if(code==='ControlRight'&&INPUT.bindings.crouchToggle==='ControlLeft')return 'crouchToggle';if(code==='ShiftRight'&&INPUT.bindings.sprint==='ShiftLeft')return 'sprint';return null}
function clearControls(){for(const k in K)K[k]=0;fh=fc=aim=jmp=0;INPUT.held.clear();INPUT.toggled=false;INPUT.crouchHeld=false;BATTLE.free.held=false}
function syntheticKey(code,down){const e=new KeyboardEvent(down?'keydown':'keyup',{code,key:keyLabel(code),bubbles:true,cancelable:true});Object.defineProperty(e,'lzMapped',{value:true});rd.domElement.dispatchEvent(e)}
function syntheticMouse(button,down){const e=new MouseEvent(down?'mousedown':'mouseup',{button,bubbles:true,cancelable:true});Object.defineProperty(e,'lzMapped',{value:true});rd.domElement.dispatchEvent(e)}
function runAction(action,down){if(action==='settings'){if(down)openSettings();return}if(action==='pause'){if(down){clearControls();if(!$('pause').classList.contains('h'))cont();else{document.exitPointerLock();paused=NET.role!=='host';$('pause').classList.remove('h')}}return}
 if(action==='crouchToggle'){if(down)INPUT.toggled=!INPUT.toggled;K.ControlLeft=INPUT.toggled||INPUT.crouchHeld?1:0;return}if(action==='crouchHold'){INPUT.crouchHeld=down;K.ControlLeft=INPUT.toggled||INPUT.crouchHeld?1:0;return}
 const canonical=ACTIONS[action][1];if(canonical.startsWith('Mouse'))syntheticMouse(Number(canonical.slice(5)),down);else syntheticKey(canonical,down)}
const settings=document.createElement('section');settings.id='settings-screen';settings.className='h';settings.innerHTML='<div class="settings-card"><header><h2>CONFIGURAÇÕES</h2><button id="settings-close" aria-label="Fechar configurações">FECHAR</button></header><p>Ctrl: toque e solte para alternar agachamento. C: segure para agachar. Evite segurar Ctrl ao usar W, pois Ctrl+W é um atalho do navegador.</p><div id="settings-note" role="status"></div><div class="settings-sliders"><label>Qualidade <select id="setting-quality"><option value="0">Leve</option><option value="1">Média</option><option value="2">Alta</option></select></label><label>Efeitos <input id="setting-effects" type="range" min="0" max="100"></label><label>Música <input id="setting-music" type="range" min="0" max="100"></label><button id="setting-fullscreen">Tela cheia</button></div><h3>TECLAS E BOTÕES DO MOUSE</h3><p>Clique em uma ação e pressione a tecla ou botão desejado. Esc cancela a escolha.</p><div id="binding-rows"></div><button id="bindings-reset" class="s">RESTAURAR PADRÃO</button></div>';document.body.append(settings);
const controlCSS=document.createElement('style');controlCSS.textContent='#settings-screen{position:fixed;inset:0;z-index:30;background:#071319eF;display:flex;align-items:center;justify-content:center;padding:12px;box-sizing:border-box}.settings-card{width:min(700px,95vw);max-height:90vh;overflow:auto;padding:20px;background:#13282e;border:1px solid #68847b;border-radius:14px}.settings-card header{display:flex;justify-content:space-between;align-items:center;gap:14px}.settings-card h2{font-size:20px;letter-spacing:2px}.settings-card p{font-size:12px;line-height:1.5;color:#c1d2c6}.settings-card button{font-size:12px;padding:8px 12px}.binding-row{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid #3c5554;padding:7px 0;font-size:13px}.binding-row button{min-width:145px;color:#dce9d9;background:#294449}.binding-row button.listening{background:#dbc38c;color:#15282b}#settings-note{color:#f2d29a;min-height:20px;font-size:12px;margin:8px 0}.settings-sliders{display:flex;gap:14px;flex-wrap:wrap;padding:12px 0}.settings-sliders label{display:flex;align-items:center;gap:6px;font-size:12px}.settings-sliders input{width:90px;accent-color:#b9cba5}.settings-sliders select{padding:7px;background:#294449;color:#dce9d9;border:1px solid #67867b;border-radius:4px}#settings-open{position:fixed;left:180px;bottom:30px;z-index:8;padding:12px 14px;font-size:12px;background:#294449;color:#dce9d9}body:not(.in-menu) #settings-open{display:none}#bindings-reset{margin-top:16px}';document.head.append(controlCSS);
function bindingRows(){const rows=$('binding-rows');rows.replaceChildren();for(const action in ACTIONS){const row=document.createElement('div');row.className='binding-row';const label=document.createElement('span');label.textContent=ACTIONS[action][0];const button=document.createElement('button');button.dataset.action=action;button.textContent=INPUT.listening===action?'PRESSIONE UMA TECLA…':bindingLabel(action);button.classList.toggle('listening',INPUT.listening===action);button.onclick=()=>{INPUT.listening=action;$('settings-note').textContent='Escolha a tecla para '+ACTIONS[action][0]+'.';bindingRows()};row.append(label,button);rows.append(row)}}
function saveBindings(){try{localStorage.setItem('lz-controls',JSON.stringify(INPUT.bindings))}catch{}}
function assignBinding(code){if(!INPUT.listening)return;if(code==='Escape'){INPUT.listening=null;$('settings-note').textContent='Escolha cancelada.';bindingRows();return}if(!validBinding(code)){$('settings-note').textContent='Essa tecla de sistema não é suportada.';return}const conflict=Object.keys(INPUT.bindings).find(a=>a!==INPUT.listening&&INPUT.bindings[a]===code);if(conflict){$('settings-note').textContent=keyLabel(code)+' já está em '+ACTIONS[conflict][0]+'. Escolha outra tecla.';return}INPUT.bindings[INPUT.listening]=code;INPUT.listening=null;saveBindings();$('settings-note').textContent='Configuração salva neste navegador.';bindingRows();updateBindingHud()}
function openSettings(){clearControls();INPUT.menuOpen=true;INPUT.listening=null;settings.classList.remove('h');document.exitPointerLock();if(state==='play')paused=NET.role!=='host';$('setting-quality').value=String(FRONTIER.quality);$('setting-effects').value=String(Math.round(SFX.volume*100));$('setting-music').value=String(Math.round(MUSIC.volume*100));$('settings-note').textContent=NET.role==='host'?'A partida online continua enquanto este menu está aberto.':'';bindingRows();$('settings-close').focus()}
function closeSettings(){INPUT.menuOpen=false;INPUT.listening=null;settings.classList.add('h');clearControls();if(state==='play'){paused=true;$('pause').classList.remove('h')}}
$('settings-close').onclick=closeSettings;$('bindings-reset').onclick=()=>{clearControls();INPUT.bindings=Object.fromEntries(Object.entries(ACTIONS).map(([k,v])=>[k,v[1]]));INPUT.listening=null;saveBindings();bindingRows();updateBindingHud();$('settings-note').textContent='Controles padrão restaurados.'};
$('setting-quality').onchange=e=>setQuality(Number(e.target.value));try{const volume=Number(localStorage.getItem('lz-effects'));if(localStorage.getItem('lz-effects')!==null&&Number.isFinite(volume))SFX.volume=Math.max(0,Math.min(1,volume))}catch{}
$('setting-effects').oninput=e=>{SFX.volume=Number(e.target.value)/100;if(SFX.bus)SFX.bus.gain.setTargetAtTime(SFX.volume,AC.currentTime,.03);try{localStorage.setItem('lz-effects',String(SFX.volume))}catch{}};
$('setting-music').oninput=e=>{MUSIC.volume=Number(e.target.value)/100;MUSIC.enabled=MUSIC.volume>0;$('music-volume').value=e.target.value;startMusic();musicLevel(true)};
$('setting-fullscreen').onclick=async()=>{try{if(!document.fullscreenElement){await document.documentElement.requestFullscreen();if(navigator.keyboard?.lock)try{await navigator.keyboard.lock()}catch{}}else{navigator.keyboard?.unlock?.();await document.exitFullscreen()}}catch{$('settings-note').textContent='Tela cheia não disponível neste navegador.'}};
const openButton=document.createElement('button');openButton.id='settings-open';openButton.textContent='⚙ CONTROLES';openButton.onclick=openSettings;document.body.append(openButton);const pauseSettings=document.createElement('button');pauseSettings.className='s';pauseSettings.style.fontSize='13px';pauseSettings.textContent='CONFIGURAÇÕES / TECLAS';pauseSettings.onclick=openSettings;$('pause').append(pauseSettings);
function gameplayInputAllowed(){return state==='play'&&!INPUT.menuOpen&&!paused&&!invOpen&&$('bigw').classList.contains('h')&&$('pause').classList.contains('h')&&!!pl[0]?.alive}
function physicalKey(e){if(e.lzMapped)return;if(INPUT.menuOpen){if(INPUT.listening){e.preventDefault();e.stopImmediatePropagation();if(e.type==='keydown'&&!e.repeat)assignBinding(e.code);return}if(e.type==='keydown'&&e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeSettings()}return}if(e.target?.matches?.('input,textarea,select'))return;if(e.ctrlKey&&gameplayInputAllowed())e.preventDefault();const action=actionFor(e.code);if(!action)return;const down=e.type==='keydown';if(!down){if(INPUT.held.has(e.code)||action==='crouchToggle'||action==='crouchHold'){e.preventDefault();e.stopImmediatePropagation();runAction(INPUT.held.get(e.code)||action,false);INPUT.held.delete(e.code)}return}if(e.repeat){if(gameplayInputAllowed()){e.preventDefault();e.stopImmediatePropagation()}return}if(action==='settings'){e.preventDefault();e.stopImmediatePropagation();openSettings();return}if(action==='pause'&&state==='play'){e.preventDefault();e.stopImmediatePropagation();runAction(action,true);return}if(!gameplayInputAllowed())return;e.preventDefault();e.stopImmediatePropagation();INPUT.held.set(e.code,action);runAction(action,true)}
function physicalMouse(e){if(e.lzMapped)return;if(INPUT.menuOpen){if(INPUT.listening&&e.type==='mousedown'){e.preventDefault();e.stopImmediatePropagation();assignBinding('Mouse'+e.button)}return}const code='Mouse'+e.button,action=actionFor(code);if(!action)return;const down=e.type==='mousedown';if(!down){if(INPUT.held.has(code)){e.preventDefault();e.stopImmediatePropagation();runAction(INPUT.held.get(code),false);INPUT.held.delete(code)}return}if(!gameplayInputAllowed()||!document.pointerLockElement)return;e.preventDefault();e.stopImmediatePropagation();INPUT.held.set(code,action);runAction(action,true)}
addEventListener('keydown',physicalKey,true);addEventListener('keyup',physicalKey,true);addEventListener('mousedown',physicalMouse,true);addEventListener('mouseup',physicalMouse,true);addEventListener('auxclick',function preventMouseNavigation(e){if(gameplayInputAllowed()&&actionFor('Mouse'+e.button))e.preventDefault()},true);
addEventListener('blur',clearControls);document.addEventListener('visibilitychange',function clearHiddenKeys(){if(document.hidden)clearControls()});document.addEventListener('pointerlockchange',function clearUnlockedKeys(){if(!document.pointerLockElement)clearControls()});
