function updateBindingHud(){for(const key of document.querySelectorAll('.battle-ui kbd')){if(!key.dataset.base)key.dataset.base=key.textContent;const base=key.dataset.base;if(base==='WASD')key.textContent=['forward','left','back','right'].map(bindingLabel).join(' ');else if(labelAction[base])key.textContent=bindingLabel(labelAction[base])}const header=$('loot-panel').querySelector('header');if(header)header.textContent=header.textContent.replace(/· E /,'· '+bindingLabel('loot')+' ');$('help').textContent=`${['forward','left','back','right'].map(bindingLabel).join('/')} mover · ${bindingLabel('sprint')} correr sem limite · ${bindingLabel('crouchToggle')} alternar agachar (toque e solte) · ${bindingLabel('crouchHold')} segurar agachar · ${bindingLabel('jump')} pular · ${bindingLabel('fire')} atirar · ${bindingLabel('aim')} mirar · ${bindingLabel('reload')} recarregar · ${bindingLabel('loot')} coletar · ${bindingLabel('free')} câmera livre · ${bindingLabel('settings')} configurações`;if(BATTLE.free.held)$('free-status').textContent='CÂMERA LIVRE · solte '+bindingLabel('free')+' para voltar'}
